function testCheckHarvest() {
  console.log(checkHarvest({ bed: "B3", crop: "Bean", kilograms: 2.6 }))
  console.log(checkHarvest({ bed: "B9", crop: "Bean", kilograms: 2.6 }))
  console.log(checkHarvest({ bed: "B3", kilograms: 2.6 }))
}

function checkHarvest(harvest) {
  const beds = ["B1", "B2", "B3", "B4", "B5", "B6", "B7", "B8"]
  let bedIsValid = false
  for (let i = 0; i < beds.length; i++) {
    if (harvest.bed === beds[i]) {
      bedIsValid = true
    }
  }
  if (bedIsValid === false) {
    return "Unknown bed"
  }
  if (harvest.crop === undefined || harvest.crop === "") {
    return "Missing crop"
  }
  const kilograms = Number(harvest.kilograms)
  if (isNaN(kilograms) || kilograms <= 0 || kilograms > 50) {
    return "Kilograms must be between 0 and 50"
  }
  return ""
}
